## Code Example
```javascript
function maxWorkload(workload, k) {
  const n = workload.length;
  const NEG = -1e15;
  const noBoost = Array.from({ length: n }, () => Array(k+1).fill(NEG));
  const boost = Array.from({ length: n }, () => Array(k+1).fill(NEG));
  noBoost[0][0] = workload[0];
  if (k >= 1) boost[0][1] = 2 * workload[0];
  for (let i = 1; i < n; i++) {
    for (let t = 0; t <= k; t++) {
      noBoost[i][t] = Math.max(noBoost[i-1][t], boost[i-1][t]) + workload[i];
    }
    for (let t = 1; t <= k; t++) {
      if (noBoost[i-1][t-1] > NEG) boost[i][t] = noBoost[i-1][t-1] + 2*workload[i];
    }
  }
  let best = NEG, bestT = 0, bestS = 0;
  for (let t = 0; t <= k; t++) {
    if (noBoost[n-1][t] > best) { best = noBoost[n-1][t]; bestT = t; bestS = 0; }
    if (boost[n-1][t] > best) { best = boost[n-1][t]; bestT = t; bestS = 1; }
  }
  // reconstruction would backtrack using saved states (omitted for brevity)
  return { maxValue: best, boostedIndices: [] };
}
```

## Why This Is Asked
New DP angle focusing on subarray range gain with exact k partitions.

## Key Concepts
- DP partitioning
- Precomputing range max/min
- Reconstruction through pointers
- Time: O(n^2 k); Space: O(nk)

## Code Example
```javascript
function maxGainKSubarrays(A, k){
  const n = A.length;
  const gain = Array.from({length:n}, ()=>Array(n).fill(0));
  for(let l=0;l<n;l++){
    let mn = A[l], mx = A[l];
    for(let r=l;r<n;r++){
      mn = Math.min(mn, A[r]);
      mx = Math.max(mx, A[r]);
      gain[l][r] = mx - mn;
    }
  }
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const take = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  dp[0][0] = 0;
  for(let i=1;i<=n;i++){
    for(let t=0;t<=Math.min(i,k);t++){
      dp[i][t] = dp[i-1][t];
      take[i][t] = take[i-1][t];
      if(t>0){
        for(let l=1;l<=i;l++){
          const val = dp[l-1][t-1] + gain[l-1][i-1];
          if(val>dp[i][t]){ dp[i][t] = val; take[i][t] = l-1; }
        }
      }
    }
  }
  const res = [];
  let i=n, t=k;
  while(t>0){
    const lminus1 = take[i][t];
    const l = lminus1 + 1;
    res.unshift([l, i]);
    i = lminus1; t--;
  }
  return {score: dp[n][k], blocks: res};
}
```

